actions.script:
notified = 0
ec.message.pushErrors()
try {
    notified = ec.resource.script("component://mr-mantle/service/mantle/smithy/Smithy.js").mirrorFailure({subTopic, messageJson}).notified
} catch (err) {
    ec.logger.error("The failure of a push mirror of " + subTopic + " was not told to its maintainers: " + (err && err.message ? err.message : err))
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

if (!partyId) return
ec.message.pushErrors()
try {
    const name = "mantle.smithy.SmithyImportServices.claim#GithubAccount"
    const accounts = Array.from(ec.entity.find("moqui.security.UserAccount").condition("partyId", partyId)
            .disableAuthz().limit(5).list()).filter(account => !!account.externalUserId)
    for (const account of accounts) {
        let later = false
        try {
            ec.service.special().name(name).parameters({userId: account.userId}).registerOnCommit()
            later = true
        } catch (err) {
            // no transaction in place: the membership is committed already
        }
        if (!later) ec.service.sync().name(name).parameters({userId: account.userId}).requireNewTransaction(true).disableAuthz().call()
    }
} catch (err) {
    ec.logger.error("The GitHub placeholders of party " + partyId + " were not claimed on joining: " + (err && err.message ? err.message : err))
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
